`, "",{"version":3,"sources":["webpack://./src/App.vue"],"names":[],"mappings":";AAyEA,mBAAA;AACA;EACA,iBAAA;EACA,qCAAA;AACA","sourcesContent":["<template>\n  <div id=\"app\">\n    <!-- 路由视图 -->\n    <transition name=\"fade\" mode=\"out-in\">\n      <router-view :key=\"$route.fullPath\" />\n    </transition>\n\n    <!-- 底部导航（仅在特定页面显示） -->\n    <nav class=\"bottom-nav\" v-if=\"showBottomNav\">\n      <router-link to=\"/\" class=\"bottom-nav-item\" active-class=\"active\">\n        <span class=\"nav-icon\">📦</span>\n        <span>物品</span>\n      </router-link>\n      <router-link to=\"/statistics\" class=\"bottom-nav-item\" active-class=\"active\">\n        <span class=\"nav-icon\">📊</span>\n        <span>统计</span>\n      </router-link>\n      <router-link to=\"/categories\" class=\"bottom-nav-item\" active-class=\"active\">\n        <span class=\"nav-icon\">🏷️</span>\n        <span>分类</span>\n      </router-link>\n      <router-link to=\"/settings\" class=\"bottom-nav-item\" active-class=\"active\">\n        <span class=\"nav-icon\">⚙️</span>\n        <span>设置</span>\n      </router-link>\n    </nav>\n  </div>\n</template>\n\n<script>\nimport { loadSettings } from '@/store/index'\n\nexport default {\n  name: 'App',\n  computed: {\n    showBottomNav() {\n      // 这些页面显示底部导航\n      const showNavRoutes = ['/', '/statistics', '/categories', '/settings']\n      return showNavRoutes.includes(this.$route.path)\n    }\n  },\n  mounted() {\n    this.applyTheme()\n  },\n  watch: {\n    $route() {\n      this.applyTheme()\n    }\n  },\n  methods: {\n    applyTheme() {\n      const settings = loadSettings()\n      const root = document.documentElement\n\n      // 跟随系统优先\n      if (settings.followSystem) {\n        const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches\n        if (prefersDark) {\n          root.setAttribute('data-theme', 'dark')\n        } else {\n          root.removeAttribute('data-theme')\n        }\n      } else if (settings.darkMode) {\n        root.setAttribute('data-theme', 'dark')\n      } else {\n        root.removeAttribute('data-theme')\n      }\n    }\n  }\n}\n</script>\n\n<style>\n/* App.vue 全局样式覆盖 */\n#app {\n  min-height: 100vh;\n  background-color: var(--bg-secondary);\n}\n</style>\n"],"sourceRoot":""}]);
