/* ============ CSS 变量 ============ */
:root {
  /* 亮色模式 */
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f5;
  --bg-card: #ffffff;
  --text-primary: #333333;
  --text-secondary: #666666;
  --text-placeholder: #999999;
  --border-color: #eeeeee;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 4px 16px rgba(0, 0, 0, 0.12);
  --accent: #409eff;
  --accent-light: #ecf5ff;
  --danger: #f56c6c;
  --danger-light: #fef0f0;
  --warning: #e6a23c;
  --warning-light: #fdf6ec;
  --success: #67c23a;
  --success-light: #f0f9eb;
  --tab-active: #409eff;
  --tab-bg: #f5f5f5;
  --fab-bg: #409eff;
  --bottom-bar-bg: #ffffff;
  --overlay-bg: rgba(0, 0, 0, 0.5);
}

:root[data-theme="dark"] {
  /* 暗色模式 */
  --bg-primary: #1a1a2e;
  --bg-secondary: #16213e;
  --bg-card: #1f2a48;
  --text-primary: #e8e8e8;
  --text-secondary: #aaaaaa;
  --text-placeholder: #666666;
  --border-color: #2a3a5a;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 4px 16px rgba(0, 0, 0, 0.4);
  --accent: #66b1ff;
  --accent-light: #1a3a5c;
  --danger: #f56c6c;
  --danger-light: #3a1a1a;
  --warning: #e6a23c;
  --warning-light: #3a2e1a;
  --success: #67c23a;
  --success-light: #1a3a1a;
  --tab-active: #66b1ff;
  --tab-bg: #16213e;
  --fab-bg: #409eff;
  --bottom-bar-bg: #1a1a2e;
  --overlay-bg: rgba(0, 0, 0, 0.7);
}

/* ============ 全局重置 ============ */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  height: 100%;
  background-color: var(--bg-secondary);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  padding-bottom: 60px; /* 底部导航占位 */
}

/* ============ Element UI 覆盖 - 暗色模式 ============ */
:root[data-theme="dark"] .el-input__inner,
:root[data-theme="dark"] .el-textarea__inner,
:root[data-theme="dark"] .el-select-dropdown,
:root[data-theme="dark"] .el-date-editor.el-input__inner {
  background-color: var(--bg-card) !important;
  border-color: var(--border-color) !important;
  color: var(--text-primary) !important;
}

:root[data-theme="dark"] .el-select-dropdown__item {
  color: var(--text-primary);
}

:root[data-theme="dark"] .el-select-dropdown__item.hover,
:root[data-theme="dark"] .el-select-dropdown__item:hover {
  background-color: var(--bg-secondary);
}

:root[data-theme="dark"] .el-picker-panel {
  background-color: var(--bg-card);
  color: var(--text-primary);
}

:root[data-theme="dark"] .el-message-box {
  background-color: var(--bg-card);
  color: var(--text-primary);
}

:root[data-theme="dark"] .el-form-item__label {
  color: var(--text-primary);
}

:root[data-theme="dark"] .el-dialog {
  background-color: var(--bg-card);
}

:root[data-theme="dark"] .el-dialog__title {
  color: var(--text-primary);
}

:root[data-theme="dark"] .el-button--text {
  color: var(--accent);
}

/* ============ 通用布局 ============ */
.page {
  min-height: 100vh;
  background-color: var(--bg-secondary);
  padding: 12px;
  padding-bottom: 72px;
}

.page-header {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-primary);
  padding: 8px 0 16px;
}

.section-title {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

/* ============ 卡片 ============ */
.card {
  background-color: var(--bg-card);
  border-radius: 12px;
  padding: 16px;
  box-shadow: var(--shadow);
  margin-bottom: 12px;
}

/* ============ 底部导航 ============ */
.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 56px;
  background-color: var(--bottom-bar-bg);
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-around;
  z-index: 100;
  box-shadow: 0 -2px 8px rgba(0, 0, 0, 0.06);
}

.bottom-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 11px;
  gap: 2px;
  padding: 4px 16px;
  cursor: pointer;
  transition: color 0.2s;
  background: none;
  border: none;
}

.bottom-nav-item.router-link-active,
.bottom-nav-item.active {
  color: var(--accent);
}

.bottom-nav-item .nav-icon {
  font-size: 22px;
  line-height: 1;
}

/* ============ 浮动按钮 ============ */
.fab {
  position: fixed;
  bottom: 72px;
  right: 20px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background-color: var(--fab-bg);
  color: white;
  border: none;
  font-size: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 12px rgba(64, 158, 255, 0.4);
  cursor: pointer;
  z-index: 99;
  transition: transform 0.2s, box-shadow 0.2s;
}

.fab:active {
  transform: scale(0.95);
  box-shadow: 0 2px 8px rgba(64, 158, 255, 0.3);
}

/* ============ 分类标签 ============ */
.cat-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 12px;
  color: white;
}

/* ============ 照片网格 ============ */
.photo-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.photo-thumb {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: 8px;
  cursor: pointer;
}

/* ============ 过渡动画 ============ */
.fade-enter-active, .fade-leave-active {
  transition: opacity 0.2s;
}
.fade-enter, .fade-leave-to {
  opacity: 0;
}

.slide-up-enter-active, .slide-up-leave-active {
  transition: all 0.3s ease;
}
.slide-up-enter, .slide-up-leave-to {
  transform: translateY(20px);
  opacity: 0;
}

/* ============ 空状态 ============ */
.empty-state {
  text-align: center;
  padding: 60px 20px;
  color: var(--text-placeholder);
}

.empty-state .empty-icon {
  font-size: 64px;
  margin-bottom: 16px;
  opacity: 0.5;
}

.empty-state p {
  font-size: 14px;
}

/* ============ 批量操作栏 ============ */
.batch-bar {
  position: fixed;
  bottom: 56px;
  left: 0;
  right: 0;
  background-color: var(--bg-card);
  border-top: 1px solid var(--border-color);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  z-index: 98;
  box-shadow: 0 -2px 8px var(--shadow);
}

/* ============ 滚动条 ============ */
::-webkit-scrollbar {
  width: 4px;
}

::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 2px;
}

/* ============ 统计页面 ============ */
.stat-card {
  background-color: var(--bg-card);
  border-radius: 12px;
  padding: 16px;
  box-shadow: var(--shadow);
  text-align: center;
}

.stat-card .stat-num {
  font-size: 32px;
  font-weight: 700;
  color: var(--accent);
}

.stat-card .stat-label {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 4px;
}

.stat-card.danger .stat-num { color: var(--danger); }
.stat-card.warning .stat-num { color: var(--warning); }
.stat-card.success .stat-num { color: var(--success); }

.bar-chart-item {
  margin-bottom: 12px;
}

.bar-chart-label {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 4px;
  display: flex;
  justify-content: space-between;
}

.bar-chart-bar-bg {
  height: 8px;
  background-color: var(--bg-secondary);
  border-radius: 4px;
  overflow: hidden;
}

.bar-chart-bar {
  height: 100%;
  border-radius: 4px;
  transition: width 0.5s ease;
}

/* ============ 工具类 ============ */
.text-danger { color: var(--danger); }
.text-warning { color: var(--warning); }
.text-success { color: var(--success); }
.text-muted { color: var(--text-secondary); font-size: 12px; }
.mt-8 { margin-top: 8px; }
.mt-12 { margin-top: 12px; }
.mt-16 { margin-top: 16px; }
.mb-8 { margin-bottom: 8px; }
.mb-12 { margin-bottom: 12px; }
.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
