/**
 * 数据层 - localStorage 读写封装
 * 所有数据操作统一从这里走，方便后续替换为后端 API
 */

import { DEFAULT_CATEGORIES } from '@/utils/constants'

// 标记是否已初始化
let _initialized = false

// ============ 工具函数 ============

function generateId() {
  return Date.now() + '_' + Math.random().toString(36).substr(2, 6)
}

function getItem(key, defaultValue = null) {
  try {
    const raw = localStorage.getItem(key)
    return raw ? JSON.parse(raw) : defaultValue
  } catch (e) {
    console.error(`读取 ${key} 失败:`, e)
    return defaultValue
  }
}

function setItem(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value))
    return true
  } catch (e) {
    console.error(`写入 ${key} 失败:`, e)
    return false
  }
}

// ============ 初始化 ============

function ensureDefaultData() {
  // 避免重复初始化
  if (_initialized) {
    console.log('[store] already initialized, skipping')
    return
  }
  _initialized = true
  console.log('[store] ensureDefaultData, categories:', localStorage.getItem('categories'))
  if (!localStorage.getItem('categories')) {
    setItem('categories', DEFAULT_CATEGORIES)
    console.log('[store] set default categories:', DEFAULT_CATEGORIES)
  }
  if (!localStorage.getItem('items')) {
    setItem('items', [])
  }
  if (!localStorage.getItem('settings')) {
    setItem('settings', { darkMode: false })
  }
}

// ============ Items ============

export function loadItems() {
  ensureDefaultData()
  return getItem('items', [])
}

export function saveItems(items) {
  return setItem('items', items)
}

export function addItem(itemData) {
  const items = loadItems()
  const newItem = {
    id: generateId(),
    price: 0,
    location: '',
    remark: '',
    photos: [],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    ...itemData
  }
  items.unshift(newItem)
  saveItems(items)
  return newItem
}

export function updateItem(id, updates) {
  const items = loadItems()
  const index = items.findIndex(i => i.id === id)
  if (index === -1) return null
  items[index] = {
    ...items[index],
    ...updates,
    updatedAt: new Date().toISOString()
  }
  saveItems(items)
  return items[index]
}

export function deleteItem(id) {
  const items = loadItems()
  const filtered = items.filter(i => i.id !== id)
  saveItems(filtered)
}

export function deleteItems(ids) {
  const items = loadItems()
  const filtered = items.filter(i => !ids.includes(i.id))
  saveItems(filtered)
}

export function getItemById(id) {
  const items = loadItems()
  return items.find(i => i.id === id) || null
}

export function moveItems(ids, newTypeId) {
  const items = loadItems()
  items.forEach(item => {
    if (ids.includes(item.id)) {
      item.typeId = newTypeId
      item.updatedAt = new Date().toISOString()
    }
  })
  saveItems(items)
}

export function updateItemsExpiry(ids, newExpiryDate) {
  const items = loadItems()
  items.forEach(item => {
    if (ids.includes(item.id)) {
      item.expiryDate = newExpiryDate
      item.updatedAt = new Date().toISOString()
    }
  })
  saveItems(items)
}

// ============ Categories ============

export function loadCategories() {
  console.log('[store] loadCategories called')
  ensureDefaultData()
  const cats = getItem('categories', DEFAULT_CATEGORIES)
  console.log('[store] loadCategories result:', cats)
  return cats
}

export function saveCategories(categories) {
  return setItem('categories', categories)
}

export function addCategory(name, color) {
  const categories = loadCategories()
  const newCat = { id: generateId(), name, color }
  categories.push(newCat)
  saveCategories(categories)
  console.log('[store] addCategory, new:', newCat, 'total:', categories.length)
  return newCat
}

export function deleteCategory(id) {
  const categories = loadCategories()
  const filtered = categories.filter(c => c.id !== id)
  saveCategories(filtered)
}

export function getCategoryById(id) {
  const categories = loadCategories()
  return categories.find(c => c.id === id) || null
}

export function isCategoryInUse(id) {
  const items = loadItems()
  return items.some(i => i.typeId === id)
}

export function getCategoryName(id) {
  const cat = getCategoryById(id)
  return cat ? cat.name : '未知分类'
}

export function getCategoryColor(id) {
  const cat = getCategoryById(id)
  return cat ? cat.color : '#999999'
}

// ============ Settings ============

export function loadSettings() {
  ensureDefaultData()
  return getItem('settings', { darkMode: false })
}

export function saveSettings(settings) {
  return setItem('settings', settings)
}

export function updateSetting(key, value) {
  const settings = loadSettings()
  settings[key] = value
  return saveSettings(settings)
}

// ============ 备份 / 恢复 ============

export function exportBackup() {
  return {
    version: '1.1',
    exportedAt: new Date().toISOString(),
    items: loadItems(),
    categories: loadCategories()
  }
}

export function importBackup(data, mode) {
  if (!data || !data.items || !data.categories) {
    throw new Error('文件格式不正确，无法导入')
  }
  if (mode === 'replace') {
    saveItems(data.items)
    saveCategories(data.categories)
  } else {
    // merge 模式：合并 categories，再合并 items（按 id 去重）
    const existingCategories = loadCategories()
    const existingCategoryIds = new Set(existingCategories.map(c => c.id))
    data.categories.forEach(c => {
      if (!existingCategoryIds.has(c.id)) {
        existingCategories.push(c)
      }
    })
    saveCategories(existingCategories)

    const existingItems = loadItems()
    const existingItemIds = new Set(existingItems.map(i => i.id))
    data.items.forEach(item => {
      if (!existingItemIds.has(item.id)) {
        existingItems.push(item)
      }
    })
    saveItems(existingItems)
  }
}

export function getLocations() {
  const items = loadItems()
  const locs = new Set()
  items.forEach(i => { if (i.location) locs.add(i.location) })
  return Array.from(locs).sort()
}

export function getStats() {
  const items = loadItems()
  const categories = loadCategories()

  const now = new Date()
  const warningDays = 7

  const total = items.length
  const expired = items.filter(i => {
    if (!i.expiryDate) return false
    return new Date(i.expiryDate) < now
  }).length

  const warning = items.filter(i => {
    if (!i.expiryDate) return false
    const d = new Date(i.expiryDate)
    const diff = (d - now) / (1000 * 60 * 60 * 24)
    return diff >= 0 && diff <= warningDays
  }).length

  // 总价值
  const totalValue = items.reduce((sum, i) => sum + (i.price || 0), 0)

  const byCategory = {}
  categories.forEach(c => {
    byCategory[c.id] = { ...c, count: 0, value: 0 }
  })
  items.forEach(i => {
    if (byCategory[i.typeId]) {
      byCategory[i.typeId].count++
      byCategory[i.typeId].value += (i.price || 0)
    }
  })

  const byLocation = {}
  items.forEach(i => {
    const loc = i.location || '未分类'
    if (!byLocation[loc]) byLocation[loc] = { count: 0, value: 0 }
    byLocation[loc].count++
    byLocation[loc].value += (i.price || 0)
  })

  return { total, expired, warning, totalValue, byCategory, byLocation }
}

export default {
  loadItems, saveItems, addItem, updateItem, deleteItem, deleteItems,
  getItemById, moveItems, updateItemsExpiry, getLocations, getStats,
  loadCategories, saveCategories, addCategory, deleteCategory,
  getCategoryById, isCategoryInUse, getCategoryName, getCategoryColor,
  loadSettings, saveSettings, updateSetting,
  exportBackup, importBackup
}
