import Vue from 'vue'
import VueRouter from 'vue-router'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    name: 'ItemList',
    component: () => import('@/views/ItemList.vue'),
    meta: { title: '物品列表' }
  },
  {
    path: '/add',
    name: 'ItemAdd',
    component: () => import('@/views/ItemForm.vue'),
    meta: { title: '新增物品' }
  },
  {
    path: '/edit/:id',
    name: 'ItemEdit',
    component: () => import('@/views/ItemForm.vue'),
    meta: { title: '编辑物品' }
  },
  {
    path: '/categories',
    name: 'CategoryManage',
    component: () => import('@/views/CategoryManage.vue'),
    meta: { title: '分类管理' }
  },
  {
    path: '/settings',
    name: 'Settings',
    component: () => import('@/views/Settings.vue'),
    meta: { title: '设置' }
  },
  {
    path: '/statistics',
    name: 'Statistics',
    component: () => import('@/views/Statistics.vue'),
    meta: { title: '统计' }
  },
  {
    path: '*',
    redirect: '/'
  }
]

const router = new VueRouter({
  mode: 'hash',
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) return savedPosition
    return { x: 0, y: 0 }
  }
})

router.afterEach((to) => {
  if (to.meta.title) {
    document.title = to.meta.title + ' - 个人物品管理'
  }
})

export default router
